/* ------------------------------------------------------------------ */
/*  Accessors                                                          */
/* ------------------------------------------------------------------ */

export const defaultAgentId = demoAgents[0].id
export const defaultRunId = '019d1766-9f94-7138-b433-2ff91272295c'

export function getRunsForAgent(agentId: string): RunSummaryView[] {
  return demoRunSummaries.filter((entry) => entry.agentId === agentId).map((entry) => entry.run)
}

export function getRunDetail(runId: string): RunDetailView | undefined {
  return demoDetails[runId]
}

function getDemoFinalAnswer(runId: string): string | undefined {
  const detail = demoDetails[runId]
  switch (detail?.projection.name) {
    case 'templated':
      return templatedFinalAnswer
    case 'mrcr-2needle':
      return mrcr2NeedleFinalAnswer
    case 'mrcr-4needle':
      return detail.projection.state === 'completed' ? mrcr4NeedleFinalAnswer : undefined
    default:
      return undefined
  }
}

/* ------------------------------------------------------------------ */
/*  Step detail                                                        */
/* ------------------------------------------------------------------ */

function buildActionRefs(step: RunStepSummaryView): string[] {
  const refs: string[] = []
  for (let i = 1; i <= step.actionCount; i++) {
    refs.push(`run-artifact://node/${step.nodeId}/step/${step.stepId}/action-${i}.json`)
  }
  return refs
}

export function getStepDetail(runId: string, stepId: string): RunStepDetailView | undefined {
  const detail = demoDetails[runId]
  if (!detail) return undefined
  const step = detail.steps.find((s) => s.stepId === stepId)
  if (!step) return undefined
  return {
    ...step,
    actionRefs: buildActionRefs(step),
  }
}

